                for (var requestedPermissionIndex = 0; requestedPermissionIndex < requestedTable.Permission.length; requestedPermissionIndex++) {
                    if (!allowedPermissionMap[requestedTable.Permission[requestedPermissionIndex]]) {
                        return { Code: 0, Msg: '数据表[' + requestedTableModel.Name + ']不允许授予所选直连权限。' };
