/*
 * V8 Event
 * TableKey: sys_role
 * EventType: SubmitAfterServerV8
 * Version: v1.0.3
 * Function:
 * - 角色提交后：在共享事务中重建菜单与表直连权限，并在角色级别变化后同步用户有效级别。
 */

var action = String(V8.FormSubmitAction || '');
if (action == 'Insert') action = 'Add';
if (action == 'Update') action = 'Upt';
if (action == 'Delete') action = 'Del';
var form = V8.Form || {};
var oldForm = V8.OldForm || {};
var roleId = String(form.Id || oldForm.Id || '');
if (!roleId) return { Code: 0, Msg: '角色 Id 为空，无法同步权限。' };

if (action == 'Del') {
    var deleteLimitsResult = V8.FormEngine.DelFormDataByWhere('sys_rolelimit', {
        _Where: [['RoleId', '=', roleId]]
    }, V8.DbTrans);
    if (!deleteLimitsResult || deleteLimitsResult.Code != 1) return deleteLimitsResult;
}

if (action == 'Add' || action == 'Upt') {
    var details;
    try {
        details = typeof form.RolePermissionDetails == 'string'
            ? JSON.parse(form.RolePermissionDetails)
            : form.RolePermissionDetails;
    } catch (error) {
        return { Code: 0, Msg: '权限明细解析失败：' + error.message };
    }
    var menuLimits = details && details.Menu ? details.Menu : [];
    var hasTableDetails = details && Object.prototype.hasOwnProperty.call(details, 'Table');
    var tableLimits = hasTableDetails && details.Table ? details.Table : [];
    var deleteMenuResult = V8.FormEngine.DelFormDataByWhere('sys_rolelimit', {
        _Where: [['RoleId', '=', roleId], ['Type', '=', 'Menu']]
    }, V8.DbTrans);
    if (!deleteMenuResult || deleteMenuResult.Code != 1) return deleteMenuResult;
    if (hasTableDetails) {
        var deleteTableResult = V8.FormEngine.DelFormDataByWhere('sys_rolelimit', {
            _Where: [['RoleId', '=', roleId], ['Type', '=', 'Table']]
        }, V8.DbTrans);
        if (!deleteTableResult || deleteTableResult.Code != 1) return deleteTableResult;
    }
    var permissionRows = [];
    for (var menuIndex = 0; menuIndex < menuLimits.length; menuIndex++) {
        permissionRows.push({
            FormEngineKey: 'sys_rolelimit',
            Id: V8.Method.NewUlid(),
            RoleId: roleId,
            FkId: menuLimits[menuIndex].Id,
            Type: 'Menu',
            Permission: menuLimits[menuIndex].Permission,
            CreateTime: V8.Action.GetDateTimeNow()
        });
    }
    for (var tableIndex = 0; hasTableDetails && tableIndex < tableLimits.length; tableIndex++) {
        permissionRows.push({
            FormEngineKey: 'sys_rolelimit',
            Id: V8.Method.NewUlid(),
            RoleId: roleId,
            FkId: tableLimits[tableIndex].Id,
            Type: 'Table',
            Permission: tableLimits[tableIndex].Permission,
            CreateTime: V8.Action.GetDateTimeNow()
        });
    }
    if (permissionRows.length > 0) {
        var addResult = V8.FormEngine.AddTableData(permissionRows, V8.DbTrans);
        if (!addResult || addResult.Code != 1) return addResult;
    }
}

function appendRoleIds(value, target) {
    if (value === null || value === undefined || value === '') return;
    if (typeof value == 'string') {
        try { appendRoleIds(JSON.parse(value), target); return; }
        catch (error) {
            var textItems = value.split(',');
            for (var textIndex = 0; textIndex < textItems.length; textIndex++) {
                var textItem = String(textItems[textIndex] || '').trim();
                if (textItem) target.push(textItem);
            }
            return;
        }
    }
    if (typeof value == 'object' && value.Id) { target.push(String(value.Id)); return; }
    if (typeof value.length == 'number') {
        for (var valueIndex = 0; valueIndex < value.length; valueIndex++) appendRoleIds(value[valueIndex], target);
    }
}

var oldLevel = parseInt(oldForm.Level || 0, 10);
var newLevel = action == 'Del' ? 0 : parseInt(form.Level || 0, 10);
if (action == 'Del' || (action == 'Upt' && oldLevel != newLevel)) {
    var roleResult = V8.FormEngine.GetTableData('sys_role', {
        _SelectFields: ['Id', 'Level'],
        _PageIndex: 1,
        _PageSize: 5000
    }, V8.DbTrans);
    if (!roleResult || roleResult.Code != 1) return roleResult;
    var levelByRoleId = {};
    for (var roleIndex = 0; roleResult.Data && roleIndex < roleResult.Data.length; roleIndex++) {
        var role = roleResult.Data[roleIndex];
        levelByRoleId[String(role.Id || '').toLowerCase()] = parseInt(role.Level || 0, 10) || 0;
    }
    var userResult = V8.FormEngine.GetTableData('sys_user', {
        _Where: [['RoleIds', 'Like', roleId]],
        _SelectFields: ['Id', 'RoleIds', 'Level'],
        _PageIndex: 1,
        _PageSize: 5000
    }, V8.DbTrans);
    if (!userResult || userResult.Code != 1) return userResult;
    for (var userIndex = 0; userResult.Data && userIndex < userResult.Data.length; userIndex++) {
        var user = userResult.Data[userIndex];
        var userRoleIds = [];
        appendRoleIds(user.RoleIds, userRoleIds);
        var maxLevel = 0;
        for (var userRoleIndex = 0; userRoleIndex < userRoleIds.length; userRoleIndex++) {
            var userRoleLevel = levelByRoleId[String(userRoleIds[userRoleIndex]).toLowerCase()] || 0;
            if (userRoleLevel > maxLevel) maxLevel = userRoleLevel;
        }
        if ((parseInt(user.Level || 0, 10) || 0) != maxLevel) {
            var updateUserResult = V8.FormEngine.UptFormData('sys_user', { Id: user.Id, Level: maxLevel }, V8.DbTrans);
            if (!updateUserResult || updateUserResult.Code != 1) return updateUserResult;
        }
    }
}
return { Code: 1 };

