  var adminRoleId = text(boundAdminRoles[0].Id);
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(adminRoleId)) throw new Error("管理员角色标识无效");
  usedTemplateIds[adminRoleId.toLowerCase()] = true;
  templateRoleIds = [adminRoleId, newTemplateId(usedTemplateIds)];
  templateDepartmentIds = [newTemplateId(usedTemplateIds), newTemplateId(usedTemplateIds)];
} catch (templateIdentityError) {
