// EMPTY_DATABASE_INSTALLED_VERSION_BASELINE_V1：只改临时副本的既有安装记录。
// 先批量读取安装身份，再按不可变包逐个读取 HDFS（最多 100 个）；每个包大小、
// SHA 和包内版本都必须一致。不能用“修改版本号”掩盖取包失败，也不替未安装应用造记录。
function buildInstalledVersionBaselineSql(stores, installedRows) {
  function literal(value) { return "'" + text(value).replace(/\\/g, "\\\\").replace(/'/g, "''") + "'"; }
  var statements = [];
  var baselines = [];
  for (var baselineIndex = 0; baselineIndex < stores.length; baselineIndex++) {
    var store = stores[baselineIndex];
    if (!isCorePlatformApp(store)) continue;
    var isInstalled = installedRows.some(function (row) {
      return text(row.StoreId) === text(store.Id)
        || (!text(row.StoreId) && text(row.AppId) === text(store.AppId || store.AppKey));
    });
    if (!isInstalled) continue;
    if (baselines.length >= 100) throw new Error("空库平台安装基线超过 100 个应用，已停止发布。");
    var content = "";
    if (text(store.PackageHdfsPath)) {
      var stored = V8.Method.GetPrivateFileText({
        OsClient: V8.OsClient,
        FilePathName: store.PackageHdfsPath,
        Limit: text(store.PackageStorageMode).toLowerCase() === "hdfsprivate",
        MaxBytes: 64 * 1024 * 1024
      });
      if (!stored || stored.Code !== 1) throw new Error("空库安装基线取包失败：" + text(store.AppKey));
      content = String(stored.Data || "");
      if (Number(System.Text.Encoding.UTF8.GetByteCount(content)) !== Number(store.PackageSize)
          || text(V8.EncryptHelper.Sha256Hex(content)).toLowerCase() !== text(store.PackageSha256).toLowerCase()) {
        throw new Error("空库安装基线包大小或 SHA 不一致：" + text(store.AppKey));
      }
    } else {
      var legacy = V8.FormEngine.GetFormData("sys_microistore", { Id: store.Id, _SelectFields: ["AppPakcet"] });
      if (!legacy || legacy.Code !== 1) throw new Error("空库安装基线旧包读取失败：" + text(store.AppKey));
      content = String(legacy.Data.AppPakcet || "");
    }
    var packageModel = JSON.parse(content);
    if (!text(store.AppVersion) || text(packageModel.PackageInfo && packageModel.PackageInfo.Version) !== text(store.AppVersion)) {
      throw new Error("空库安装基线商城版本与包内版本不一致：" + text(store.AppKey));
    }
    var proof = {
      BaselineType: "OfficialEmptyDatabaseSnapshot",
      AppId: text(store.AppId || store.AppKey),
      Version: text(store.AppVersion),
      PackageSha256: text(V8.EncryptHelper.Sha256Hex(content)).toLowerCase(),
      PackageSize: Number(System.Text.Encoding.UTF8.GetByteCount(content))
    };
    baselines.push(proof);
    statements.push("UPDATE sys_microistoreversion v JOIN sys_microistore s ON s.Id=" + literal(store.Id)
      + " AND (v.StoreId=s.Id OR (COALESCE(v.StoreId,'')='' AND v.AppId=COALESCE(NULLIF(s.AppId,''),s.AppKey)))"
      + " SET v.StoreId=s.Id,v.AppVersion=s.AppVersion,v.AppVersionInstall=s.AppVersion,v.PackageVersion=s.AppVersion,"
      + "v.InstallStatus='Installed',v.InstallOsClient='iTdos',v.InstallUserId='',v.InstallUserName='',"
      + "v.InstallResult=" + literal(JSON.stringify(proof)) + ",v.Remark='官方空数据库快照安装基线（已校验包内容）'"
      + " WHERE s.AppVersion=" + literal(store.AppVersion)
      + (text(store.PackageHdfsPath)
        ? " AND LOWER(COALESCE(s.PackageSha256,''))=" + literal(text(store.PackageSha256).toLowerCase())
        : " AND SHA2(COALESCE(s.AppPakcet,''),256)=" + literal(proof.PackageSha256)) + ";");
  }
  return { Sql: statements.join("\n"), Baselines: baselines };
}
var installedVersionBaseline;
try {
  var installedRows = toArray(V8.Db.FromSql("SELECT StoreId, AppId FROM sys_microistoreversion WHERE COALESCE(IsDeleted,0)=0").ToArray());
  installedVersionBaseline = buildInstalledVersionBaselineSql(storeRows, installedRows);
} catch (baselineError) {
  return { Code: 0, Msg: text(baselineError.message || baselineError) };
}

