function text(value) {
  return value === null || value === undefined ? "" : String(value).trim();
}

function report(current, message) {
  if (!backgroundTaskId || !V8.Method || typeof V8.Method.UpdateBackgroundTask !== "function") return;
  V8.Method.UpdateBackgroundTask({
    _BackgroundTaskId: backgroundTaskId,
    Current: current,
    Total: 8,
    Progress: Math.floor(current * 100 / 8),
    Msg: message,
    Message: message
  });
}

function cleanup() {
  try {
    if (V8.Method && typeof V8.Method.CleanupEmptyDatabaseRelease === "function") {
      return V8.Method.CleanupEmptyDatabaseRelease(baseParam);
    }
  } catch (cleanupEx) {
    console.error("CleanupEmptyDatabaseRelease", cleanupEx && cleanupEx.message ? cleanupEx.message : cleanupEx);
  }
  return null;
}

function fail(message, data, needCleanup) {
  if (needCleanup) cleanup();
  report(0, message);
  return {
    Code: 0,
    Msg: message,
    Data: data || null
  };
}

function continueWith(checkpoint, current, message, dataAppend, nextDelaySeconds) {
  report(current, message);
  return {
    Code: 1,
    Msg: message,
    Data: {
      BackgroundTask: {
        HasMore: true,
        Checkpoint: checkpoint,
        Current: current,
        Total: 8,
        NextDelaySeconds: nextDelaySeconds || 0,
        Msg: message
      }
    },
    DataAppend: dataAppend || {}
  };
}

function isPrepareReleaseLeaseBusy(result) {
  // EMPTY_DATABASE_RELEASE_LEASE_WAIT_V1: the host guarantees this exact
  // diagnostic is raised before touching the temporary database. The task
  // lease and release lease expire independently after an interrupted worker.
  return result && result.Code === 0 && text(result.Msg).indexOf(
    "另一项主库空数据库发布任务仍在执行，当前任务未修改临时数据库。"
  ) >= 0;
}

function audit(title, content, level) {
  try {
    V8.Method.AddSysLog({
      Type: "安全审计",
      Title: title,
      Content: JSON.stringify(content || {}),
      Level: level
    });
  } catch (auditEx) {
    console.error("EmptyDatabaseReleaseAudit", auditEx && auditEx.message ? auditEx.message : auditEx);
  }
}

