            OsClient: text(childTask.OsClient),
            Name: text(childTask.Name),
            TaskId: childTaskId,
            Status: childStatus,
            Progress: childProgress,
            Msg: text(row.Msg)
        });
    } else if (childStatus == 'Failed' || childStatus == 'Canceled') {
        terminalFailures.push({
            OsClient: text(childTask.OsClient),
            Name: text(childTask.Name),
            TaskId: childTaskId,
            Status: childStatus,
            Progress: childProgress,
            Msg: text(row.Msg)
        });
    } else {
