        Code: 0,
        Data: {
            FailureStage: 'ChildTerminal',
            TargetCount: totalTargetCount,
            SucceededCount: succeeded.length,
            FailedCount: terminalFailures.length,
            Results: succeeded,
            Failures: terminalFailures
        },
