    var totals = { RequestCount: 0, ErrorCount: 0, SlowCount: 0, ReceivedBytes: 0, SentBytes: 0, TotalBytes: 0, DurationMs: 0, MaxDurationMs: 0, AnonymousCount: 0, UploadCount: 0, DownloadCount: 0, SuspiciousCount: 0 };
